    @Test func vectorResizingFromUInt8() {
        let mismatches = Mismatches("portVectorResizingU8ToI16InVectorCode")
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0xD41C_803B_820D_00F3)
        for a in aInputs {
            let port = { () -> SIMD<Int16> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int16>.self, capacity: 1) { result in
                    unsafe portVectorResizingU8ToI16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int16> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int16>.self, capacity: 1) { result in
                    unsafe highwayVectorResizingU8ToI16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

